/* Behaviour of the static pages. Every feature checks that its elements exist,
   so one script serves the landing (WebGL hero) and all topic pages. */
/* Old single-page anchors (/vi#work, /en#system/eval ...) now live on topic pages. */
(function legacyHashes(){
 if(!document.body.classList.contains('page-home'))return;
 const h=decodeURIComponent(location.hash.slice(1));if(!h)return;
 const loc=document.documentElement.lang==='vi'?'vi':'en';
 const map={domains:'projects',work:'projects',strategy:'strategy',operating:'strategy',approach:'strategy',learning:'feedback',bottlenecks:'feedback',engineering:'reliability'};
 if(h.startsWith('system/')){location.replace('/'+loc+'/projects#'+h);return}
 if(h==='notes'||h.startsWith('note/')){location.replace('/'+loc+'/blog');return}
 if(map[h])location.replace('/'+loc+'/'+map[h]+'#'+h);
})();
'use strict';

